import socket,struct,sys,time,json,statistics

def exact(s,n):
 b=bytearray()
 while len(b)<n:
  x=s.recv(n-len(b))
  if not x:raise EOFError
  b+=x
 return b
if sys.argv[1]=='server':
 with socket.socket() as listener:
  listener.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
  listener.bind(('10.55.0.1',19443));listener.listen(1);listener.settimeout(60)
  print('ready',flush=True)
  conn,_=listener.accept()
  with conn:
   conn.settimeout(15);conn.setsockopt(socket.IPPROTO_TCP,socket.TCP_NODELAY,1)
   try:
    while True:
     size,reply=struct.unpack('<II',exact(conn,8))
     assert 0<size<=65536 and 0<reply<=65536
     exact(conn,size);conn.sendall(bytes(reply))
   except EOFError:pass
else:
 result=[]
 with socket.create_connection(('10.55.0.1',19443),timeout=10) as conn:
  conn.setsockopt(socket.IPPROTO_TCP,socket.TCP_NODELAY,1)
  for size,reply in [(8,8),(5280,10240),(31680,61440)]:
   for pause in [0,0.001]:
    samples=[];data=struct.pack('<II',size,reply)+bytes(size)
    for i in range(220):
     if pause:time.sleep(pause)
     start=time.perf_counter_ns();conn.sendall(data);exact(conn,reply)
     if i>=20:samples.append((time.perf_counter_ns()-start)/1000)
    ordered=sorted(samples)
    result.append(dict(request=size,response=reply,pause_seconds=pause,median_us=statistics.median(samples),p90_us=ordered[180],min_us=min(samples),max_us=max(samples),samples_us=samples))
 print(json.dumps(result,indent=2))
